import { isPreviewDeployment } from '@/config/seo';
import { renderNewsFeed } from '@/features/news/server/feed';
import { getNewsFeedItems } from '@/features/news/server/news';

// News is published from Git; the feed is regenerated by the same deployment.
export const dynamic = 'force-static';

export async function GET(): Promise<Response> {
  if (isPreviewDeployment()) {
    return new Response('Not Found', { status: 404, headers: { 'X-Robots-Tag': 'noindex' } });
  }
  return new Response(renderNewsFeed(await getNewsFeedItems()), {
    headers: { 'Content-Type': 'application/atom+xml; charset=utf-8', 'X-Robots-Tag': 'noindex' },
  });
}
